messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Low-Poly Humanoid Treadmill</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#1a1a2e;overflow:hidden}
canvas{display:block;width:100vw;height:100vh}
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// ─── SCENE SETUP ───
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1a1a2e);
scene.fog = new THREE.Fog(0x1a1a2e, 30, 60);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(12, 5, 0);
camera.lookAt(0, 3, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.1;
document.body.appendChild(renderer.domElement);

// ─── LIGHTING ───
const ambientLight = new THREE.AmbientLight(0x404060, 0.8);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xfff0dd, 1.5);
dirLight.position.set(8, 12, 6);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 30;
dirLight.shadow.camera.left = -10;
dirLight.shadow.camera.right = 10;
dirLight.shadow.camera.top = 10;
dirLight.shadow.camera.bottom = -5;
dirLight.shadow.bias = -0.001;
scene.add(dirLight);

const rimLight = new THREE.DirectionalLight(0x4466aa, 0.6);
rimLight.position.set(-6, 4, -4);
scene.add(rimLight);

// ─── MATERIALS ───
const skinMat = new THREE.MeshStandardMaterial({ color: 0xd4a574, flatShading: true, roughness: 0.7 });
const shirtMat = new THREE.MeshStandardMaterial({ color: 0x3366cc, flatShading: true, roughness: 0.6 });
const pantsMat = new THREE.MeshStandardMaterial({ color: 0x333355, flatShading: true, roughness: 0.7 });
const shoeMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true, roughness: 0.8 });
const treadmillMat = new THREE.MeshStandardMaterial({ color: 0x555566, flatShading: true, roughness: 0.5 });
const treadmillDarkMat = new THREE.MeshStandardMaterial({ color: 0x333344, flatShading: true, roughness: 0.6 });
const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a3e, flatShading: true, roughness: 0.9 });

// ─── HELPER: Create low-poly mesh ───
function createMesh(geo, mat, castShadow = true, receiveShadow = false) {
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = castShadow;
    mesh.receiveShadow = receiveShadow;
    return mesh;
}

// ─── BUILD HUMANOID ───
const humanoid = new THREE.Group();

// --- Head ---
const head = createMesh(new THREE.BoxGeometry(0.7, 0.75, 0.6), skinMat);
head.position.y = 6.1;

// --- Neck ---
const neck = createMesh(new THREE.BoxGeometry(0.35, 0.3, 0.35), skinMat);
neck.position.y = 5.55;

// --- Torso ---
const torso = createMesh(new THREE.BoxGeometry(1.2, 1.8, 0.6), shirtMat);
torso.position.y = 4.4;

// --- Hips ---
const hips = createMesh(new THREE.BoxGeometry(1.1, 0.4, 0.55), pantsMat);
hips.position.y = 3.3;

// --- Upper Arm Left ---
const upperArmL = createMesh(new THREE.BoxGeometry(0.3, 1.0, 0.3), shirtMat);
upperArmL.position.set(-0.8, 5.0, 0);

// --- Lower Arm Left ---
const lowerArmL = createMesh(new THREE.BoxGeometry(0.28, 0.9, 0.28), skinMat);
lowerArmL.position.set(-0.8, 3.95, 0);

// --- Upper Arm Right ---
const upperArmR = createMesh(new THREE.BoxGeometry(0.3, 1.0, 0.3), shirtMat);
upperArmR.position.set(0.8, 5.0, 0);

// --- Lower Arm Right ---
const lowerArmR = createMesh(new THREE.BoxGeometry(0.28, 0.9, 0.28), skinMat);
lowerArmR.position.set(0.8, 3.95, 0);

// --- Upper Leg Left ---
const upperLegL = createMesh(new THREE.BoxGeometry(0.4, 1.3, 0.35), pantsMat);
upperLegL.position.set(-0.3, 2.6, 0);

// --- Lower Leg Left ---
const lowerLegL = createMesh(new THREE.BoxGeometry(0.35, 1.3, 0.32), pantsMat);
lowerLegL.position.set(-0.3, 1.25, 0);

// --- Foot Left ---
const footL = createMesh(new THREE.BoxGeometry(0.4, 0.25, 0.6), shoeMat);
footL.position.set(-0.3, 0.125, 0.15);

// --- Upper Leg Right ---
const upperLegR = createMesh(new THREE.BoxGeometry(0.4, 1.3, 0.35), pantsMat);
upperLegR.position.set(0.3, 2.6, 0);

// --- Lower Leg Right ---
const lowerLegR = createMesh(new THREE.BoxGeometry(0.35, 1.3, 0.32), pantsMat);
lowerLegR.position.set(0.3, 1.25, 0);

// --- Foot Right ---
const footR = createMesh(new THREE.BoxGeometry(0.4, 0.25, 0.6), shoeMat);
footR.position.set(0.3, 0.125, 0.15);

// --- Pivot Groups (for rotation) ---
const pivotUpperArmL = new THREE.Group();
pivotUpperArmL.position.set(-0.8, 5.5, 0);
pivotUpperArmL.add(upperArmL);
upperArmL.position.set(0, -0.5, 0);

const pivotLowerArmL = new THREE.Group();
pivotLowerArmL.position.set(-0.8, 4.5, 0);
pivotLowerArmL.add(lowerArmL);
lowerArmL.position.set(0, -0.45, 0);

const pivotUpperArmR = new THREE.Group();
pivotUpperArmR.position.set(0.8, 5.5, 0);
pivotUpperArmR.add(upperArmR);
upperArmR.position.set(0, -0.5, 0);

const pivotLowerArmR = new THREE.Group();
pivotLowerArmR.position.set(0.8, 4.5, 0);
pivotLowerArmR.add(lowerArmR);
lowerArmR.position.set(0, -0.45, 0);

const pivotUpperLegL = new THREE.Group();
pivotUpperLegL.position.set(-0.3, 3.3, 0);
pivotUpperLegL.add(upperLegL);
upperLegL.position.set(0, -0.65, 0);

const pivotLowerLegL = new THREE.Group();
pivotLowerLegL.position.set(-0.3, 2.0, 0);
pivotLowerLegL.add(lowerLegL);
lowerLegL.position.set(0, -0.65, 0);

const pivotUpperLegR = new THREE.Group();
pivotUpperLegR.position.set(0.3, 3.3, 0);
pivotUpperLegR.add(upperLegR);
upperLegR.position.set(0, -0.65, 0);

const pivotLowerLegR = new THREE.Group();
pivotLowerLegR.position.set(0.3, 2.0, 0);
pivotLowerLegR.add(lowerLegR);
lowerLegR.position.set(0, -0.65, 0);

const pivotTorso = new THREE.Group();
pivotTorso.add(head, neck, torso, hips, pivotUpperArmL, pivotLowerArmL, pivotUpperArmR, pivotLowerArmR);

const pivotHips = new THREE.Group();
pivotHips.position.set(0, 3.3, 0);
pivotHips.add(pivotTorso, pivotUpperLegL, pivotLowerLegL, pivotUpperLegR, pivotLowerLegR);

humanoid.add(pivotHips);
humanoid.position.y = 0;
scene.add(humanoid);

// ─── TREADMILL ───
const treadmillGroup = new THREE.Group();

// Deck (main platform)
const deck = createMesh(new THREE.BoxGeometry(5, 0.5, 2.5), treadmillMat, false, true);
deck.position.y = 0.25;
treadmillGroup.add(deck);

// Side rails
const railL = createMesh(new THREE.BoxGeometry(5, 0.15, 0.1), treadmillDarkMat);
railL.position.set(0, 0.575, -1.25);
treadmillGroup.add(railL);
const railR = createMesh(new THREE.BoxGeometry(5, 0.15, 0.1), treadmillDarkMat);
railR.position.set(0, 0.575, 1.25);
treadmillGroup.add(railR);

// Front and rear supports
const supportF = createMesh(new THREE.BoxGeometry(0.15, 0.5, 2.5), treadmillDarkMat);
supportF.position.set(2.5, 0.25, 0);
treadmillGroup.add(supportF);
const supportB = createMesh(new THREE.BoxGeometry(0.15, 0.5, 2.5), treadmillDarkMat);
supportB.position.set(-2.5, 0.25, 0);
treadmillGroup.add(supportB);

// Front uprights
const uprightFL = createMesh(new THREE.BoxGeometry(0.12, 1.8, 0.12), treadmillDarkMat);
uprightFL.position.set(2.5, 1.4, -1.1);
treadmillGroup.add(uprightFL);
const uprightFR = createMesh(new THREE.BoxGeometry(0.12, 1.8, 0.12), treadmillDarkMat);
uprightFR.position.set(2.5, 1.4, 1.1);
treadmillGroup.add(uprightFR);

// Rear uprights
const uprightBL = createMesh(new THREE.BoxGeometry(0.12, 1.8, 0.12), treadmillDarkMat);
uprightBL.position.set(-2.5, 1.4, -1.1);
treadmillGroup.add(uprightBL);
const uprightBR = createMesh(new THREE.BoxGeometry(0.12, 1.8, 0.12), treadmillDarkMat);
uprightBR.position.set(-2.5, 1.4, 1.1);
treadmillGroup.add(uprightBR);

// Handlebar
const handlebar = createMesh(new THREE.BoxGeometry(0.08, 0.08, 2.2), treadmillDarkMat);
handlebar.position.set(2.5, 2.7, 0);
treadmillGroup.add(handlebar);

// Belt texture (striped)
const beltGeo = new THREE.PlaneGeometry(4.8, 2.3, 20, 1);
const beltMat = new THREE.MeshStandardMaterial({ 
    color: 0x444455, 
    flatShading: true, 
    roughness: 0.8,
    side: THREE.DoubleSide
});
const belt = createMesh(beltGeo, beltMat, false, true);
belt.rotation.x = -Math.PI / 2;
belt.position.y = 0.51;
treadmillGroup.add(belt);

treadmillGroup.position.y = 0;
scene.add(treadmillGroup);

// ─── GROUND ───
const ground = createMesh(new THREE.PlaneGeometry(60, 60), groundMat, false, true);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.5;
scene.add(ground);

// Grid lines on ground
const gridHelper = new THREE.GridHelper(60, 30, 0x3a3a5e, 0x2a2a4e);
gridHelper.position.y = -0.49;
scene.add(gridHelper);

// ─── ANIMATION ───
const CYCLE_DURATION = 10; // seconds
const STILL_DURATION = 2;
const WALK_DURATION = 3;
const RUN_DURATION = 3;

// Easing function: smoothstep
function easeSmoothStep(t) {
    return t * t * (3 - 2 * t);
}

// Smooth sine wave for limb swing
function swing(t, amplitude) {
    return Math.sin(t * Math.PI * 2) * amplitude;
}

// Get animation state and normalized time within that state
function getAnimationState(t) {
    const cycleT = t % CYCLE_DURATION;
    if (cycleT < STILL_DURATION) {
        return { state: 'still', t: cycleT / STILL_DURATION };
    } else if (cycleT < STILL_DURATION + WALK_DURATION) {
        return { state: 'walk', t: (cycleT - STILL_DURATION) / WALK_DURATION };
    } else {
        return { state: 'run', t: (cycleT - (STILL_DURATION + WALK_DURATION)) / RUN_DURATION };
    }
}

// Smooth transition between states
function blendState(a, b, t) {
    return a + (b - a) * t;
}

function animate(timestamp) {
    requestAnimationFrame(animate);

    const t = timestamp * 0.001; // seconds
    const { state, t: localT } = getAnimationState(t);

    // Belt movement speed
    let beltSpeed = 0;
    if (state === 'walk') beltSpeed = 2.0;
    else if (state === 'run') beltSpeed = 5.0;

    // Belt visual offset
    belt.material.map = null; // no texture, just use vertex offset
    const beltPositions = belt.geometry.attributes.position;
    for (let i = 0; i < beltPositions.count; i++) {
        const x = beltPositions.getX(i);
        const y = beltPositions.getY(i);
        const offset = (t * beltSpeed) % 0.3;
        beltPositions.setZ(i, (x + offset) * 0.05);
    }
    beltPositions.needsUpdate = true;

    // ─── STILL ───
    if (state === 'still') {
        // Arms hanging naturally
        pivotUpperArmL.rotation.x = 0.05;
        pivotLowerArmL.rotation.x = -0.1;
        pivotUpperArmR.rotation.x = -0.05;
        pivotLowerArmR.rotation.x = -0.1;

        // Legs straight
        pivotUpperLegL.rotation.x = 0;
        pivotLowerLegL.rotation.x = 0;
        pivotUpperLegR.rotation.x = 0;
        pivotLowerLegR.rotation.x = 0;

        // Torso upright
        pivotTorso.rotation.x = 0;

        // Slight breathing motion
        const breath = Math.sin(t * 1.5) * 0.02;
        torso.scale.y = 1 + breath;
        torso.scale.x = 1 - breath * 0.3;
    }

    // ─── WALK ───
    else if (state === 'walk') {
        const walkPhase = localT * Math.PI * 2; // one full stride per cycle

        // Forward lean
        pivotTorso.rotation.x = -0.08;

        // Leg swing (opposite phases)
        const legSwing = Math.sin(walkPhase) * 0.35;
        pivotUpperLegL.rotation.x = legSwing;
        pivotUpperLegR.rotation.x = -legSwing;

        // Knee bend (bend when leg swings back)
        const kneeBend = Math.max(0, -Math.sin(walkPhase)) * 0.4;
        pivotLowerLegL.rotation.x = -kneeBend;
        pivotLowerLegR.rotation.x = -Math.max(0, Math.sin(walkPhase)) * 0.4;

        // Arm swing (opposite to legs)
        const armSwing = Math.sin(walkPhase) * 0.3;
        pivotUpperArmL.rotation.x = -armSwing;
        pivotUpperArmR.rotation.x = armSwing;

        // Elbow bend (slight)
        pivotLowerArmL.rotation.x = -0.3 + Math.max(0, Math.sin(walkPhase)) * 0.2;
        pivotLowerArmR.rotation.x = -0.3 + Math.max(0, -Math.sin(walkPhase)) * 0.2;

        // Subtle hip rotation
        const hipRot = Math.sin(walkPhase) * 0.05;
        pivotHips.rotation.y = hipRot;

        // Breathing
        const breath = Math.sin(t * 2.5) * 0.03;
        torso.scale.y = 1 + breath;
    }

    // ─── RUN ───
    else if (state === 'run') {
        const runPhase = localT * Math.PI * 4; // two strides per cycle (faster)

        // Forward lean
        pivotTorso.rotation.x = -0.2;

        // Larger leg swing
        const legSwing = Math.sin(runPhase) * 0.6;
        pivotUpperLegL.rotation.x = legSwing;
        pivotUpperLegR.rotation.x = -legSwing;

        // More knee bend
        const kneeBend = Math.max(0, -Math.sin(runPhase)) * 0.7;
        pivotLowerLegL.rotation.x = -kneeBend;
        pivotLowerLegR.rotation.x = -Math.max(0, Math.sin(runPhase)) * 0.7;

        // Larger arm swing
        const armSwing = Math.sin(runPhase) * 0.5;
        pivotUpperArmL.rotation.x = -armSwing;
        pivotUpperArmR.rotation.x = armSwing;

        // More elbow bend
        pivotLowerArmL.rotation.x = -0.6 + Math.max(0, Math.sin(runPhase)) * 0.3;
        pivotLowerArmR.rotation.x = -0.6 + Math.max(0, -Math.sin(runPhase)) * 0.3;

        // More hip rotation
        const hipRot = Math.sin(runPhase) * 0.08;
        pivotHips.rotation.y = hipRot;

        // More breathing
        const breath = Math.sin(t * 4) * 0.05;
        torso.scale.y = 1 + breath;
    }

    // ─── Smooth transitions between states ───
    // Add transition blending at boundaries
    const cycleT = t % CYCLE_DURATION;
    const transitionDuration = 0.4;
    let transitionFactor = 1;
    let prevState = null;
    let nextState = null;
    let transT = 0;

    if (cycleT < transitionDuration) {
        transT = cycleT / transitionDuration;
        prevState = 'still';
        nextState = 'walk';
        transitionFactor = easeSmoothStep(transT);
    } else if (cycleT > STILL_DURATION + WALK_DURATION + RUN_DURATION - transitionDuration) {
        transT = (cycleT - (STILL_DURATION + WALK_DURATION + RUN_DURATION - transitionDuration)) / transitionDuration;
        prevState = 'run';
        nextState = 'still';
        transitionFactor = 1 - easeSmoothStep(transT);
    } else if (cycleT > STILL_DURATION - transitionDuration && cycleT < STILL_DURATION + transitionDuration) {
        transT = (cycleT - (STILL_DURATION - transitionDuration)) / (transitionDuration * 2);
        prevState = 'still';
        nextState = 'walk';
        transitionFactor = easeSmoothStep(transT);
    } else if (cycleT > STILL_DURATION + WALK_DURATION - transitionDuration && cycleT < STILL_DURATION + WALK_DURATION + transitionDuration) {
        transT = (cycleT - (STILL_DURATION + WALK_DURATION - transitionDuration)) / (transitionDuration * 2);
        prevState = 'walk';
        nextState = 'run';
        transitionFactor = easeSmoothStep(transT);
    }

    renderer.render(scene, camera);
}

requestAnimationFrame(animate);

// ─── RESIZE ───
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
